package com.terraformers.modernization.evaluation.opus;

import static org.assertj.core.api.Assertions.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.file.Path;
import java.nio.file.Files;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class OpusGenerationEvaluationTest {
    @TempDir Path temp;
    private final ObjectMapper mapper=new ObjectMapper();
    private final Path root=Path.of("..").toAbsolutePath().normalize();
    private OpusGenerationFixtureLoader.LoadedFixture fixture(){return new OpusGenerationFixtureLoader(mapper).load(root.resolve("evaluation/opus-generation-v1/manifest.json"),root.resolve("evaluation/terraformers-eval-v1/dataset.json"),root.resolve("corpus/terraformers-reference/v3/documents.jsonl"));}

    @Test void loadsSixUniqueCasesAndPreservesReferenceOrder(){var f=fixture();assertThat(f.cases()).hasSize(6);assertThat(f.cases()).extracting(c->c.definition().caseId()).doesNotHaveDuplicates();assertThat(f.cases().get(0).references()).extracting(r->r.id()).containsExactlyElementsOf(f.cases().get(0).referenceIds());}

    @Test void requestUsesFrozenClaudeContractAndSemanticPrompt(){var c=fixture().cases().get(0);var runner=new OpusGenerationEvaluationRunner(mapper,r->null,8192);var request=runner.request(c,false);assertThat(request.path("anthropic_version").asText()).isEqualTo("vertex-2023-10-16");assertThat(request.path("messages").get(0).path("content").get(0).path("source").path("media_type").asText()).isEqualTo("image/webp");assertThat(request.path("messages").get(0).path("content").get(1).path("text").asText()).contains("Classification and output rules:",c.referenceIds().get(0));assertThat(request.path("output_config").path("format").path("type").asText()).isEqualTo("json_schema");assertThat(request.toString()).doesNotContain("minimum","maximum","Authorization","Bearer");assertThat(request.path("output_config").path("format").path("schema").path("required")).hasSize(8);}

    @Test void parsesArchitectureAndScoresResources(){String text="{\"inputType\":\"ARCHITECTURE_DIAGRAM\",\"classificationConfidence\":0.9,\"classificationReason\":\"diagram\",\"summary\":\"system\",\"components\":[],\"relationships\":[],\"warnings\":[],\"terraformCode\":\"resource \\\"aws_vpc\\\" \\\"main\\\" { cidr_block = \\\"10.0.0.0/16\\\" }\\nresource \\\"aws_lb\\\" \\\"main\\\" { name = \\\"main\\\" }\"}";var c=fixture().cases().get(0);var evidence=new OpusGenerationEvaluationRunner(mapper,r->new ClaudeVertexClient.ClaudeResponse(text,"end_turn",10,20,"claude-opus-5-5"),8192).evaluate(c);assertThat(evidence.observedClassification()).isEqualTo("ARCHITECTURE_DIAGRAM");assertThat(evidence.requiredResourceTypesMatched()).contains("aws_vpc","aws_lb");assertThat(evidence.requiredResourceTypesMissing()).contains("aws_db_instance","aws_security_group");assertThat(evidence.firstFailureCategory()).isEqualTo("GENERATION_REQUIRED_RESOURCE_MISSING");}

    @Test void retriesTruncationOnlyOnce(){var responses=new ArrayDeque<>(List.of(new ClaudeVertexClient.ClaudeResponse("{}","max_tokens",1,8192,"claude-opus-5-5"),new ClaudeVertexClient.ClaudeResponse("{}","max_tokens",1,8192,"claude-opus-5-5")));var evidence=new OpusGenerationEvaluationRunner(mapper,r->responses.remove(),8192).evaluate(fixture().cases().get(0));assertThat(evidence.compactRetryOccurred()).isTrue();assertThat(evidence.firstFailureCategory()).isEqualTo("OUTPUT_TRUNCATED");assertThat(responses).isEmpty();}

    @Test void negativeTerraformIsExplicitAndResponseFormatFailure(){String text="{\"inputType\":\"AMBIGUOUS\",\"classificationConfidence\":0.7,\"classificationReason\":\"cropped\",\"summary\":\"\",\"components\":[],\"relationships\":[],\"warnings\":[],\"terraformCode\":\"resource \\\"aws_vpc\\\" \\\"bad\\\" { cidr_block = \\\"x\\\" }\"}";var c=fixture().cases().get(4);var e=new OpusGenerationEvaluationRunner(mapper,r->new ClaudeVertexClient.ClaudeResponse(text,"end_turn",1,2,"claude-opus-5-5"),8192).evaluate(c);assertThat(e.terraformEmitted()).isTrue();assertThat(e.responseFormatPassed()).isFalse();assertThat(e.firstFailureCategory()).isEqualTo("RESPONSE_FORMAT");}

    @Test void classifiesHttpAccessAndRuntimeFailures(){assertThat(GoogleClaudeVertexClient.failureCategory(401)).isEqualTo("MODEL_ACCESS");assertThat(GoogleClaudeVertexClient.failureCategory(403)).isEqualTo("MODEL_ACCESS");assertThat(GoogleClaudeVertexClient.failureCategory(429)).isEqualTo("PROVIDER_RUNTIME");assertThat(GoogleClaudeVertexClient.failureCategory(503)).isEqualTo("PROVIDER_RUNTIME");}

    @Test void recordsAccessAndQuotaFailuresWithoutQualityResults(){var c=fixture().cases().get(0);var access=new OpusGenerationEvaluationRunner(mapper,r->{throw new GoogleClaudeVertexClient.ClaudeProviderException(403,"MODEL_ACCESS","Claude Vertex rawPredict returned HTTP 403");},8192).evaluate(c);assertThat(access.firstFailureCategory()).isEqualTo("MODEL_ACCESS");assertThat(access.httpStatus()).isEqualTo(403);assertThat(access.observedClassification()).isNull();var quota=new OpusGenerationEvaluationRunner(mapper,r->{throw new GoogleClaudeVertexClient.ClaudeProviderException(429,"PROVIDER_RUNTIME","Claude Vertex rawPredict returned HTTP 429");},8192).evaluate(c);assertThat(quota.firstFailureCategory()).isEqualTo("PROVIDER_RUNTIME");assertThat(quota.httpStatus()).isEqualTo(429);assertThat(quota.generatedTerraform()).isEmpty();}

    @Test void recordsTransportFailureAndContinuesAllCases(){AtomicInteger calls=new AtomicInteger();ClaudeVertexClient client=request->{if(calls.incrementAndGet()==2)throw new GoogleClaudeVertexClient.ClaudeProviderException(null,"PROVIDER_RUNTIME","HttpTimeoutException");return new ClaudeVertexClient.ClaudeResponse("{}","end_turn",null,null,"claude-opus-5-5");};var loaded=fixture();var artifact=OpusGenerationEvaluationLauncher.run(loaded,new OpusGenerationEvaluationRunner(mapper,client,8192),"run","source","claude-opus-5-5","global",8192);assertThat(artifact.cases()).hasSize(6);assertThat(artifact.cases().get(1).firstFailureCategory()).isEqualTo("PROVIDER_RUNTIME");assertThat(artifact.cases().get(1).failureReason()).isEqualTo("HttpTimeoutException");assertThat(artifact.cases().get(2).caseId()).isEqualTo(loaded.cases().get(2).definition().caseId());assertThat(artifact.promptContractSourceCommit()).isEqualTo("3fc610f1e9d601a4d5f79f281b358b783342c4ce");}

    @Test void promptHashIsDeterministic(){var c=fixture().cases().get(0);ClaudeVertexClient client=request->new ClaudeVertexClient.ClaudeResponse("{}","end_turn",null,null,"claude-opus-5-5");var runner=new OpusGenerationEvaluationRunner(mapper,client,8192);assertThat(runner.evaluate(c).renderedPromptSha256()).isEqualTo(runner.evaluate(c).renderedPromptSha256()).hasSize(64);}

    @Test void fixtureShaMismatchFailsClosed() throws Exception {var manifest=mapper.readTree(Files.readString(root.resolve("evaluation/opus-generation-v1/manifest.json")));manifest.path("cases").get(0).path("inputSha256");((com.fasterxml.jackson.databind.node.ObjectNode)manifest.path("cases").get(0)).put("inputSha256","0".repeat(64));Path changed=temp.resolve("manifest.json");mapper.writeValue(changed.toFile(),manifest);assertThatThrownBy(()->load(changed,root.resolve("corpus/terraformers-reference/v3/documents.jsonl"))).hasMessageContaining("fixture SHA mismatch");}

    @Test void missingCorpusDocumentFailsClosed() throws Exception {var manifest=mapper.readTree(Files.readString(root.resolve("evaluation/opus-generation-v1/manifest.json")));((com.fasterxml.jackson.databind.node.ArrayNode)manifest.path("cases").get(0).path("orderedReferenceIds")).set(0,mapper.getNodeFactory().textNode("missing-document"));Path changed=temp.resolve("manifest.json");mapper.writeValue(changed.toFile(),manifest);assertThatThrownBy(()->load(changed,root.resolve("corpus/terraformers-reference/v3/documents.jsonl"))).hasMessageContaining("missing corpus document");}

    @Test void duplicateCorpusDocumentFailsClosed() throws Exception {Path source=root.resolve("corpus/terraformers-reference/v3/documents.jsonl");List<String> lines=new ArrayList<>(Files.readAllLines(source));lines.add(lines.get(0));Path duplicate=temp.resolve("documents.jsonl");Files.write(duplicate,lines);assertThatThrownBy(()->load(root.resolve("evaluation/opus-generation-v1/manifest.json"),duplicate)).hasMessageContaining("duplicate corpus document ID");}

    @Test void placeholderCommentDoesNotInvalidateUsableDraft(){String terraform=requiredTerraform(fixture().cases().get(0))+"\n# placeholder";var e=evaluate(0,"ARCHITECTURE_DIAGRAM",terraform);assertThat(e.firstFailureCategory()).isEqualTo("NONE");assertThat(e.placeholderExampleDetected()).isFalse();}

    @Test void forbiddenResourceIsRecorded(){String terraform=requiredTerraform(fixture().cases().get(0))+"\nresource \"aws_cloudfront_distribution\" \"bad\" { enabled = true }";var e=evaluate(0,"ARCHITECTURE_DIAGRAM",terraform);assertThat(e.forbiddenResourceTypesPresent()).containsExactly("aws_cloudfront_distribution");assertThat(e.firstFailureCategory()).isEqualTo("GENERATION_FORBIDDEN_RESOURCE");}

    @Test void classificationMismatchPrecedesTerraformQuality(){var original=fixture().cases().get(0);var d=original.definition();var changed=new com.terraformers.modernization.evaluation.EvaluationCase(d.schemaVersion(),d.datasetVersion(),d.caseId(),d.input(),com.terraformers.modernization.evaluation.EvaluationCase.InputClassification.NON_ARCHITECTURE_IMAGE,d.components(),d.relationships(),d.resourceTypes(),d.retrieval(),d.generation(),d.validation(),d.notes());var c=new OpusGenerationFixtureLoader.FixtureCase(changed,original.imageBytes(),original.referenceIds(),original.references());String terraform=requiredTerraform(original)+"\nresource \"aws_cloudfront_distribution\" \"bad\" { enabled = true }";String text="{\"inputType\":\"ARCHITECTURE_DIAGRAM\",\"classificationConfidence\":0.9,\"classificationReason\":\"test\",\"summary\":\"system\",\"components\":[],\"relationships\":[],\"warnings\":[],\"terraformCode\":"+quote(terraform)+"}";var e=new OpusGenerationEvaluationRunner(mapper,r->new ClaudeVertexClient.ClaudeResponse(text,"end_turn",1,2,"claude-opus-5-5"),8192).evaluate(c);assertThat(e.firstFailureCategory()).isEqualTo("INPUT_CLASSIFICATION");assertThat(e.forbiddenResourceTypesPresent()).isNotEmpty();}

    private OpusGenerationFixtureLoader.LoadedFixture load(Path manifest,Path corpus){return new OpusGenerationFixtureLoader(mapper).load(manifest,root.resolve("evaluation/terraformers-eval-v1/dataset.json"),corpus);}
    private OpusGenerationEvaluationRunner.CaseEvidence evaluate(int index,String classification,String terraform){String text="{\"inputType\":\""+classification+"\",\"classificationConfidence\":0.9,\"classificationReason\":\"test\",\"summary\":\"system\",\"components\":[],\"relationships\":[],\"warnings\":[],\"terraformCode\":"+quote(terraform)+"}";var c=fixture().cases().get(index);return new OpusGenerationEvaluationRunner(mapper,r->new ClaudeVertexClient.ClaudeResponse(text,"end_turn",1,2,"claude-opus-5-5"),8192).evaluate(c);}
    private String requiredTerraform(OpusGenerationFixtureLoader.FixtureCase c){StringBuilder out=new StringBuilder();for(String type:c.definition().generation().terraformResourceTypes().required())out.append("resource \"").append(type).append("\" \"test\" { name = \"test\" }\n");return out.toString();}
    private String quote(String value){try{return mapper.writeValueAsString(value);}catch(Exception exception){throw new AssertionError(exception);}}
}
